insert into content_blocks (page_key, section_key, content) values ('home','site_config','{"name":"Jai Jinendra Namkeens","legalName":"Jai Jinendra Namkeens","tagline":"Artisanal Savouries & Royal Sweets","description":"Authentic Rajasthani namkeens, mithai, and festive hampers - freshly fried, nitrogen-sealed, and delivered pan-India. 100% shuddh vegetarian since 1982.","url":"https://jaijinendra.com","phone":"+91 1800-JAI-NAMKEEN","email":"hello@jaijinendra.com","fssai":"10020014002931","founded":1982,"social":{"instagram":"https://instagram.com/JaiJinendraNamkeens"},"announcement":"FREE PAN-INDIA DELIVERY ON ORDERS ABOVE ₹999 • Freshly Handcrafted & Nitrogen Packed • 100% Shuddh Shakahari (Pure Vegetarian)","announcementMobile":"Free delivery above ₹999 · Fresh & nitrogen-packed · 100% Pure Veg","logo":{"src":"/brand/logo-namkeens.png","alt":"Jai Jinendra Namkeens - Sweets, Namkeens, Bakery","width":1774,"height":887},"logoMark":{"src":"/brand/logo-mark.png","alt":"Jai Jinendra mark","width":543,"height":480},"brandLogo":{"src":"/brand/logo.png","alt":"Jai Jinendra - Sweets, Namkeens, Bakery","width":1774,"height":887}}'::jsonb),('home','hero_slides','[{"id":"diwali","src":"/images/hero0.jpg","alt":"Celebrate the Joy of Diwali - Authentic Indian Festive Treats - Jai Jinendra Namkeens"},{"id":"namkeen","src":"/images/hero1.jpg","alt":"Crisp. Savory. Authentic. Handcrafted Indian Snacks - Jai Jinendra Namkeens"}]'::jsonb),('home','trust_items','[{"id":"ingredients","title":"Premium Ingredients","mobileTitle":"Pure Ingredients","description":"Single-origin spices & 100% pure desi ghee.","mobileDescription":"Desi ghee & single-origin spices","icon":"eco"},{"id":"packed","title":"Freshly Packed","mobileTitle":"Fresh Daily","description":"Small batch daily fry with nitrogen seals.","mobileDescription":"Nitrogen-sealed same day","icon":"package"},{"id":"shuddh","title":"100% Pure Shuddh","mobileTitle":"100% Pure Veg","description":"Strict pure-veg dedicated kitchen facility.","mobileDescription":"Dedicated shuddh kitchen","icon":"veg"},{"id":"shipping","title":"Pan-India Express","mobileTitle":"Pan-India","description":"Dispatched in 24 hrs to 26,000+ pin codes.","mobileDescription":"Dispatched in 24 hrs","icon":"shipping"}]'::jsonb) on conflict (page_key, section_key) do update set content=excluded.content;
